const paths={back:'m15 5-7 7 7 7',arrow:'M5 12h14m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',close:'m6 6 12 12M6 18 18 6',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',search:'m21 21-4.5-4.5M19 11a8 8 0 1 1-16 0 8 8 0 0 1 16 0',home:'m3 10 9-7 9 7v10h-6v-7H9v7H3Z',car:'m4 8 2-5h12l2 5M3 8h18v10H3Zm3 10v3m12-3v3M6 12h.01M18 12h.01',wallet:'M21 7H4a2 2 0 0 1 0-4h14v4m3 0v14H4a2 2 0 0 1-2-2V5m19 6h-6v6h6',user:'M20 21v-2a7 7 0 0 0-14 0v2M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',bell:'M18 8a6 6 0 0 0-12 0c0 8-3 8-3 9h18c0-1-3-1-3-9M10 21h4',clock:'M22 12A10 10 0 1 1 2 12a10 10 0 0 1 20 0ZM12 6v6l4 2',shield:'m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6Zm-4 10 3 3 5-6',chat:'M21 3H3v14h5l4 4 4-4h5Z',phone:'M4 3h4l2 5-3 2c2 4 3 5 7 7l2-3 5 2v4c-9 4-20-7-17-17Z',layers:'m12 2 10 6-10 6L2 8Zm-10 10 10 6 10-6M2 17l10 6 10-6',location:'m22 2-7 20-4-9-9-4Z',plus:'M12 5v14M5 12h14',check:'m4 12 5 5L20 6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM10 2h4l1 3 4 2 3 1v4l-3 2-2 4-1 4h-4l-2-3-4-2-3-1v-4l3-2 2-4Z',file:'M14 2H4v20h16V8Zm0 0v6h6M8 13h8M8 17h6',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',chart:'M3 3v18h19M7 16v-5m6 5V6m6 10V9',help:'M22 12A10 10 0 1 1 2 12a10 10 0 0 1 20 0ZM9 8a3 3 0 0 1 6 0c0 3-3 2-3 5m0 4h.01',gift:'M3 8h18v4H3Zm2 4v10h14V12M12 8v14M12 8C3 8 4 0 9 3c2 1 3 5 3 5Zm0 0c9 0 8-8 3-5-2 1-3 5-3 5Z',lock:'M6 10V6a6 6 0 0 1 12 0v4M4 10h16v12H4Zm8 4v4',send:'m22 2-7 20-4-9-9-4Zm0 0L11 13'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.help}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const img=(name,cls='')=>`<img class="${cls}" src="assets/${name}.png" alt="${name==='auto'?'Auto-rickshaw':name==='bike'?'Bike':'Cab'}">`;
const vehicles=[{id:'auto',name:'Auto',detail:'Everyday easy · 3 seats',fare:146,eta:3},{id:'bike',name:'Bike',detail:'Light on traffic · 1 seat',fare:92,eta:2},{id:'mini',name:'Mini',detail:'A little extra comfort · 4 seats',fare:208,eta:4},{id:'sedan',name:'Sedan',detail:'More room to settle in · 4 seats',fare:264,eta:5},{id:'suv',name:'SUV',detail:'Bring your whole crew · 6 seats',fare:348,eta:6}];
const common=[['activity','Your rides'],['wallet','Wallet'],['account','Account'],['personal','Personal details'],['saved','Saved places'],['family','Your people'],['preferences','Preferences'],['safety','Safety centre'],['support','Help & support'],['notifications','Notifications'],['privacy','Privacy & account'],['chat','Trip chat'],['auth','Sign in'],['onboarding','Account setup']];
const screens={rider:[['home','Home'],['search','Pickup & destination'],['choose','Choose your ride'],['confirm','Review your ride'],['matching','Finding a Captain'],['tracking','Captain arriving'],['trip','On your way'],['receipt','Trip complete'],['payment','Payment'],['plan','Plan a ride'],['rewards','Rewards'],['ledger','Transactions'],...common.filter(([id])=>id!=='onboarding')],captain:[['home','Drive dashboard'],['request','Incoming request'],['pickup','Head to pickup'],['otp','Start the ride'],['trip','On trip'],['collect','Collect payment'],['receipt','Trip complete'],['earnings','Earnings'],['ledger','Transactions'],['tools','Driver tools'],['vehicle','Vehicle & documents'],['insights','Driving insights'],['demand','Demand nearby'],...common.filter(([id])=>!['saved','family','wallet'].includes(id))]};
const flow={rider:['home','search','choose','confirm','matching','tracking','trip','receipt','payment','home'],captain:['home','request','pickup','otp','trip','collect','receipt','earnings','home']};
const state={rider:{screen:'home',vehicle:'auto',destination:'Chennai Airport',payment:'Cash',tab:'Past',sort:'Recommended',toggles:{notifications:true},step:0,stars:0,chat:[]},captain:{screen:'home',vehicle:'auto',destination:'Chennai Airport',payment:'Cash',tab:'Past',sort:'Today',online:false,toggles:{notifications:true},step:0,stars:0,chat:[]}};
const currentVehicle=s=>vehicles.find(v=>v.id===s.vehicle)||vehicles[0];
const primary=(label,screen)=>`<button class="primary" data-go="${screen}"><span>${label}</span>${icon('arrow')}</button>`;
const action=(label,name)=>`<button class="primary" data-action="${name}"><span>${label}</span>${icon('arrow')}</button>`;
const row=(title,detail,ico,go)=>`<button class="list-row" data-go="${go}"><span class="list-symbol">${icon(ico)}</span><span class="list-copy"><strong>${title}</strong><small>${detail}</small></span>${icon('chevron','chevron')}</button>`;
const modalRow=(title,detail,ico,name)=>row(title,detail,ico,'').replace('data-go=""',`data-modal="${name}"`);
const intro=(eyebrow,title,copy='')=>`<div class="intro"><span class="kicker">${eyebrow}</span><h2>${title}</h2>${copy?`<p>${copy}</p>`:''}</div>`;
const tabs=(items,current,kind)=>`<div class="tabs" role="tablist" aria-label="${kind}">${items.map(x=>`<button role="tab" aria-selected="${x===current}" class="${x===current?'active':''}" data-tab="${esc(x)}" data-kind="${kind}">${x}</button>`).join('')}</div>`;
const field=(label,id,value='',type='text',placeholder='')=>`<label class="field-label" for="${id}">${label}</label><input class="input" id="${id}" type="${type}" value="${esc(value)}" placeholder="${placeholder}">`;
const metric=(label,value,detail='')=>`<div class="metric"><small>${label}</small><strong>${value}</strong>${detail?`<p>${detail}</p>`:''}</div>`;
const route=s=>`<div class="route"><div class="route-row"><span class="route-dot"></span><div><small>Pickup</small><strong>2nd Cross Street, Adyar</strong></div></div><div class="route-row"><span class="route-dot"></span><div><small>Destination</small><strong>${esc(s.destination)}</strong></div></div></div>`;
const driver=(role,s)=>`<div class="driver"><span class="avatar">${role==='rider'?'A':'D'}</span><div><strong>${role==='rider'?'Arun Kumar':'Deepa Rider'}</strong><small>${role==='rider'?'Verified Captain · ★ 4.9':'Your rider · pickup confirmed'}</small>${role==='rider'?'<span class="plate">TN 09 AB 1234</span>':''}</div>${role==='rider'?img(s.vehicle):''}</div>`;
function building(x,y,w,h){const d=15;return `<g><path d="M${x},${y-h}l${w},-18 ${d},11 -${w},18Z" fill="#fff"/><path d="M${x},${y-h}l${d},11v${h}l-${d},-11Z" fill="#d7e1d1"/><path d="M${x+d},${y-h+11}l${w},-18v${h}l-${w},18Z" fill="#e6ece0"/>${[0,1,2].map(i=>`<path d="M${x+d+6},${y-h+22+i*11}l${w-11},-13" stroke="#f8faf5" stroke-width="4"/>`).join('')}</g>`;}
function map(s,role){return `<div class="map" aria-label="Illustrative Chennai map for design preview" role="img"><svg class="city-map" viewBox="0 0 390 650" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><rect width="390" height="650" fill="#e8eee1"/><path d="M0 400Q90 360 175 430T390 450V650H0Z" fill="#dce7d0"/><path d="M-80 640L445 100M-50 325L450 650M-60 80L470 420" stroke="#fff" stroke-width="49"/><path d="M-80 640L445 100M-50 325L450 650M-60 80L470 420" stroke="#e0e7d9" stroke-width="36"/><path d="M-80 640L445 100M-50 325L450 650M-60 80L470 420" stroke="#fff" stroke-width="1.5" stroke-dasharray="12 14"/>${building(15,175,46,54)}${building(81,210,44,76)}${building(180,133,55,64)}${building(253,179,46,71)}${building(296,292,60,85)}${building(202,326,41,59)}${building(31,388,49,67)}${building(89,435,47,47)}${building(256,511,55,60)}${building(337,442,48,72)}<path d="M110 398L206 298L253 249" fill="none" stroke="${role==='rider'?'#e95a45':'#d9b42c'}" stroke-width="5" stroke-linecap="round" stroke-dasharray="${['home','demand'].includes(s.screen)?'0':'8 8'}" opacity="${s.screen==='home'?'.25':'.95'}"/><g fill="#afc7a2" stroke="#e9f0e3" stroke-width="2"><circle cx="43" cy="244" r="12"/><circle cx="69" cy="257" r="10"/><circle cx="345" cy="174" r="15"/><circle cx="285" cy="386" r="13"/><circle cx="325" cy="589" r="19"/></g><text x="78" y="290" font-family="Inter,sans-serif" font-size="9" fill="#91a582" letter-spacing="2">ADYAR</text><text x="280" y="356" font-family="Inter,sans-serif" font-size="8" fill="#9aaa90" letter-spacing="1.5">GUINDY</text></svg>${img(s.vehicle,'map-vehicle')}<span class="location-dot"></span>${s.screen!=='home'?'<span class="map-pin"></span>':''}</div><div class="map-context">${icon('pin')} ${s.screen==='home'?'Adyar, Chennai':s.screen==='demand'?'Illustrative demand · Chennai':'Adyar → Airport'}</div><div class="map-controls"><button class="icon-button" aria-label="Map layers" data-modal="layers">${icon('layers')}</button><button class="icon-button" aria-label="Centre map" data-action="centre">${icon('location')}</button></div>`;}
function header(role,s,title,back=true){return `<header class="app-head"><div class="left">${back?`<button class="icon-button flat" aria-label="Back" data-action="back">${icon('back')}</button><h1>${title}</h1>`:`<span class="wordmark">hop<small>${role.toUpperCase()}</small></span>`}</div><div class="tools">${!back?`<button class="icon-button" aria-label="Plan a ride" data-go="${role==='rider'?'plan':'tools'}">${icon(role==='rider'?'clock':'settings')}</button><button class="icon-button" aria-label="Notifications" data-go="notifications">${icon('bell')}</button>`:`<button class="icon-button" aria-label="Help" data-go="support">${icon('help')}</button>`}</div></header>`;}
function nav(role,s){const items=role==='rider'?[['home','home','Ride'],['activity','clock','Activity'],['wallet','wallet','Wallet'],['account','user','Account']]:[['home','location','Drive'],['earnings','chart','Earnings'],['activity','clock','Trips'],['account','user','Account']];return `<nav class="bottom-nav" aria-label="${role} navigation">${items.map(([go,ico,label])=>`<button data-go="${go}" class="${s.screen===go?'active':''}" ${s.screen===go?'aria-current="page"':''}>${icon(ico)}${label}</button>`).join('')}</nav>`;}
const switchRow=(key,title,detail,s)=>`<button class="switch-row" role="switch" aria-checked="${!!s.toggles[key]}" data-toggle="${key}"><span><strong>${title}</strong><small>${detail}</small></span><i class="switch" aria-hidden="true"></i></button>`;
function view(role,s){const captain=role==='captain',v=currentVehicle(s);let title=s.screen==='activity'&&captain?'Your trips':s.screen==='preferences'?(captain?'Driving preferences':'Ride preferences'):screens[role].find(([id])=>id===s.screen)?.[1]||'Hop',body='',footer='',isMap=false,hasNav=['home','account','activity','wallet','earnings'].includes(s.screen);let sheet='';
 switch(s.screen){
 case 'home':isMap=true;sheet=captain?`<div class="row"><span class="online-status ${s.online?'on':''}"><i></i>${s.online?'You’re online':'You’re offline'}</span><span class="badge">Chennai</span></div><h2>Your day, your pace.</h2><p>${s.online?'You’re ready for your next trip.':'Good journeys start when you’re ready.'}</p><div class="metric-grid">${metric('Today’s earnings','₹1,240','6 completed trips')}${metric('Daily goal','62%','₹1,240 of ₹2,000')}</div><div class="row"><small class="muted">Your workday, made simpler</small><button class="text-button" data-go="tools">Driver tools →</button></div><button class="primary" data-action="online"><span>${s.online?'Go offline':'Go online'}</span>${icon('arrow')}</button>`:`<span class="kicker">A LITTLE CLOSER, WITH HOP</span><h2>Where to next?</h2><p>Your everyday journey, made a little easier.</p><button class="destination" data-go="search">${icon('search')}Where are you going?<span class="arrow">→</span></button><div class="saved-row"><button class="saved-place" data-destination="Home">${icon('home')}<span><strong>Home</strong><small>Adyar · 2nd Cross Street</small></span></button><button class="saved-place" data-destination="Work">${icon('file')}<span><strong>Work</strong><small>Olympia Tech Park</small></span></button></div><div class="products">${vehicles.slice(0,3).map(x=>`<button class="product ${s.vehicle===x.id?'active':''}" data-home-vehicle="${x.id}">${img(x.id)}${x.name}</button>`).join('')}</div>`;break;
 case 'search':body=`${intro('YOUR JOURNEY STARTS HERE','Where are we going?')}<div class="search-field">${icon('pin')}<input aria-label="Pickup location" value="2nd Cross Street, Adyar"></div><div class="search-field">${icon('search')}<input aria-label="Search destination" data-search placeholder="Search a place or address" autocomplete="off"></div><div class="row"><button class="text-button" data-modal="stops">+ Add a stop</button><button class="text-button" data-go="plan">${icon('clock')} Plan ahead</button></div><div class="section-heading">Your familiar places</div><div data-places>${places()}</div><div class="hint">Prefer to choose on the map? You can fine-tune your pickup after selecting your destination.</div>`;break;
 case 'choose':isMap=true;sheet=`<div class="row"><h2>A ride that fits.</h2><span class="badge">8.6 km</span></div><p>Adyar → ${esc(s.destination)} · about 22 min</p>${tabs(['Recommended','Lowest fare'],s.sort,'sort')}${vehicles.map(x=>`<button class="vehicle-card ${s.vehicle===x.id?'selected':''}" role="radio" aria-checked="${s.vehicle===x.id}" data-vehicle="${x.id}">${img(x.id)}<span class="copy"><strong>${x.name}</strong><small>${x.detail}</small></span><span class="fare"><strong>₹${x.fare}</strong><small>${x.eta} min away</small></span><i class="radio" aria-hidden="true"></i></button>`).join('')}`;footer=primary('Continue','confirm');break;
 case 'confirm':isMap=true;sheet=`<div class="row"><h2>All set to go?</h2><span class="badge">${v.name}</span></div><div class="route-summary">${route(s)}</div><div class="group">${modalRow('Payment method',s.payment,'wallet','payment')}${modalRow('Riding for','Me · add a passenger','user','passenger')}${modalRow('Ride preferences','Sharing, accessibility & more','settings','ride-options')}${modalRow('Promo code','Have a little something saved?','gift','promo')}</div>`;footer=`<div class="row"><div><small>Estimated fare</small><strong>₹${v.fare}</strong></div><button class="text-button" data-modal="fare">View breakdown</button></div>${primary('Find a Captain','matching')}<p>Review everything before requesting your ride.</p>`;break;
 case 'matching':isMap=true;sheet=`<span class="kicker">FINDING YOUR CAPTAIN</span><h2>A good ride is<br>on its way.</h2><p>Looking for an available ${v.name.toLowerCase()} near your pickup.</p><div class="loading-line" role="status" aria-label="Searching for a Captain"><i></i></div><div class="route-summary">${route(s)}</div><div class="row"><span class="small muted">Requested fare</span><strong>₹${v.fare}</strong></div><div class="icon-actions"><button data-modal="cancel">${icon('close')}Cancel</button><button data-modal="offers">${icon('chat')}Offers</button><button data-go="safety">${icon('shield')}Safety</button></div>`;break;
 case 'tracking':case 'pickup':case 'trip':isMap=true;title=s.screen==='trip'?(captain?'On trip':'On your way'):captain?'Head to pickup':'Your Captain is coming';sheet=`<div class="row"><div><span class="kicker">${s.screen==='trip'?'ON YOUR WAY':captain?'PICKUP CONFIRMED':'YOUR CAPTAIN IS COMING'}</span><h2>${s.screen==='trip'?'Next stop:<br>your plans.':captain?'Meet your rider.':'Meet Arun in 4 min.'}</h2></div><div class="eta">${s.screen==='trip'?'18':'4'}<small>MIN AWAY</small></div></div>${driver(role,s)}${!captain&&s.screen!=='trip'?'<div class="code-display"><span>Your pickup code<br><small>Share when you meet</small></span><strong>431602</strong></div>':`<div class="route-summary">${route(s)}</div>`}<div class="icon-actions"><button data-modal="call">${icon('phone')}Call</button><button data-go="chat">${icon('chat')}Message</button><button data-go="safety">${icon('shield')}Safety</button></div>`;if(captain)footer=primary(s.screen==='trip'?'Complete trip':'I’ve arrived',s.screen==='trip'?'collect':'otp');else footer=`<button class="secondary" data-modal="${s.screen==='trip'?'share':'trip-details'}">${s.screen==='trip'?'Share this journey':'Trip details & cancellation'}</button>`;break;
 case 'otp':body=`<div class="empty"><div class="round-symbol">${icon('lock')}</div><span class="kicker">ONE QUICK CHECK</span><h2>Ready for the ride?</h2><p>Ask your rider for the six-digit pickup code.<br>Start only when they’re safely on board.</p></div><div class="pin-entry"><input aria-label="Six-digit pickup code" data-code inputmode="numeric" maxlength="6" placeholder="······" autocomplete="off"></div><p class="small muted" style="text-align:center">Enter six digits to explore the next preview screen.</p><div class="card">${driver(role,s)}${route(s)}</div>`;footer=action('Verify & start ride','verify-code');break;
 case 'receipt':body=`<div class="empty"><div class="round-symbol">${icon('check')}</div><span class="kicker">A GOOD LITTLE JOURNEY</span><h2>${captain?'Another trip, well done.':'You’ve arrived.'}</h2><p>${captain?'Thank you for moving your city.':'Thanks for riding with Hop.'}</p><div class="large-amount">₹${v.fare}</div><span class="badge ${captain?'':'pending'}">${captain?'Trip completed':'Payment awaiting confirmation'}</span></div><div class="receipt-route">${route(s)}</div>${!captain?`<div style="text-align:center"><strong>How was your journey?</strong><div class="stars">${[1,2,3,4,5].map(n=>`<button aria-label="Rate ${n} stars" data-star="${n}" class="${s.stars>=n?'selected':''}">★</button>`).join('')}</div></div>`:`<div class="metric-grid">${metric('Trip distance','8.6 km')}${metric('Trip time','22 min')}</div>`}<div class="group">${modalRow('Trip statement','Fare, route & payment information','file','statement')}${row('Need help with this trip?','We’re here when you need us','help','support')}</div>`;footer=primary(captain?'Back to driving':'Review payment',captain?'home':'payment');break;
 case 'payment':case 'collect':body=`${intro(captain?'THE FINAL STEP':'YOUR PAYMENT',captain?'One last little thing.':'Simple money moments.',captain?'Check the payment method before recording receipt.':'Choose how you’d like to pay for this journey.')}<div class="empty" style="padding:10px 0 25px"><span class="kicker">TRIP FARE</span><div class="large-amount">₹${v.fare}</div><span class="badge pending">Awaiting confirmation</span></div><div class="group">${modalRow('Payment method',s.payment,'wallet','payment')}${modalRow('Fare breakdown','Your trip, clearly itemised','file','fare')}</div><div class="hint">${captain?'Record cash only after receiving it. Online payment status must be verified by the payment provider.':'Your receipt is confirmed only after payment verification.'}</div>`;footer=captain?primary('Preview receipt','receipt'):action('Preview payment step','payment-preview');break;
 case 'activity':body=`${tabs(captain?['Ongoing','Past']:['Ongoing','Upcoming','Past'],s.tab,'history')}${tripCard(s,s.tab==='Upcoming'?'Tomorrow, 9:00 AM':'Today, 10:24 AM',s.tab==='Ongoing'?'In progress':s.tab==='Upcoming'?'Scheduled':'Completed')}${s.tab==='Past'?tripCard({...s,destination:'Chennai Central'},'Yesterday, 6:40 PM','Completed'):''}<div class="hint">Your trips stay together, with receipts and support close by.</div>`;break;
 case 'wallet':body=`<div class="balance-card"><span class="kicker">YOUR HOP WALLET</span>${icon('wallet')}<div class="amount">₹680<span style="font-size:23px;opacity:.55">.00</span></div><p>A little ready for your next ride.</p><button class="secondary" data-modal="topup">${icon('plus')} Add money</button></div><div class="card row"><span class="list-symbol">${icon('gift')}</span><div style="flex:1"><strong>A little off your next ride.</strong><p class="small muted" style="margin:5px 0 0">Explore your rewards and offers.</p></div><button class="text-button" data-go="rewards">View</button></div><div class="section-heading">Recent transactions <small>Last 30 days</small></div><div class="group">${row('Added to wallet','Today · UPI top-up','plus','ledger')}${row('Ride to Chennai Airport','Yesterday · ₹146','car','receipt')}${row('Ride to Chennai Central','30 Oct · ₹188','car','receipt')}</div>`;break;
 case 'earnings':body=`${tabs(['Today','Week','Month'],s.sort==='Recommended'?'Today':s.sort,'sort')}<div class="balance-card"><span class="kicker">${s.sort==='Week'?'THIS WEEK':s.sort==='Month'?'THIS MONTH':'TODAY’S EARNINGS'}</span>${icon('chart')}<div class="amount">${s.sort==='Week'?'₹8,420':s.sort==='Month'?'₹32,680':'₹1,240'}</div><p>Completed trip fares · sample totals</p></div><div class="metric-grid">${metric('Completed trips','6')}${metric('Time on the road','4 h 20 m')}</div><div class="section-heading">Your week <small>₹ · completed fares</small></div><div class="card"><div class="chart" role="img" aria-label="Illustrative earnings over seven days">${[54,70,43,87,65,94,76].map((h,i)=>`<div class="${i===6?'active':''}" style="--h:${h}%"><small>${['M','T','W','T','F','S','S'][i]}</small></div>`).join('')}</div></div><div class="group">${row('Transactions & payouts','Your money, clearly organised','wallet','ledger')}${row('Driving insights','Distance, fares & rider feedback','chart','insights')}${modalRow('Daily goal','₹1,240 of ₹2,000','settings','goal')}</div>`;break;
 case 'account':body=`<div class="profile"><span class="avatar">${captain?'A':'D'}</span><div><strong>${captain?'Arun Kumar':'Deepa Rider'}</strong><p>Verified mobile account</p></div></div>${captain?`<div class="card row"><span class="badge">Approved Captain</span><button class="text-button" data-go="vehicle">View vehicle →</button></div>`:''}<div class="account-section"><small>YOUR PROFILE</small><div class="group">${row('Personal details','Your name, contact & preferences','user','personal')}${row(captain?'Vehicle & documents':'Saved places',captain?'Registration, licence & insurance':'Home, Work and your familiar places',captain?'car':'pin',captain?'vehicle':'saved')}${row(captain?'Driver tools':'Your people',captain?'Daily goals, home mode & breaks':'Family & favourite Captains',captain?'settings':'heart',captain?'tools':'family')}</div></div><div class="account-section"><small>YOUR JOURNEY</small><div class="group">${row(captain?'Driving preferences':'Ride preferences','Make Hop work for you','settings','preferences')}${row('Safety centre','Help is always close by','shield','safety')}${row('Notifications','Ride and account updates','bell','notifications')}</div></div><div class="account-section"><small>MORE FROM HOP</small><div class="group">${row('Help & support','We’re here when you need us','help','support')}${!captain?row('Rewards & referrals','Good journeys add up','gift','rewards'):row('Captain application','Your submitted details & documents','file','onboarding')}${row('Privacy & account','Your data and account controls','lock','privacy')}</div></div>`;break;
 case 'personal':body=`<div class="profile"><span class="avatar">${captain?'A':'D'}</span><div><strong>${captain?'Arun Kumar':'Deepa Rider'}</strong><p>Make yourself at home.</p></div></div>${field('Full name',`${role}-name`,captain?'Arun Kumar':'Deepa Rider')}<div class="section-heading">Contact details</div><div class="group">${modalRow('Mobile number','+91 98765 43210 · Verified','phone','mobile')}${modalRow('Email address','Add an email for your receipts','user','email')}${modalRow('Personal information','Gender & date of birth','user','personal-more')}${!captain?modalRow('Business receipts','Company, GSTIN & cost centre','file','business'):''}</div>`;footer=action('Save details','save');break;
 case 'preferences':body=`${intro('MAKE IT YOURS',captain?'Your workday, your way.':'Your ride, your way.','A few small choices for a more comfortable journey.')}<div class="group">${captain?modalRow('Pickup radius','3 km around your location','pin','radius')+modalRow('Minimum fare','₹40 per trip','wallet','minimum-fare'):modalRow('Default vehicle',v.name,'car','vehicle-default')+modalRow('Default payment',s.payment,'wallet','payment')}</div><div class="section-heading">App settings</div><div class="group">${modalRow('Language','English','chat','language')}${switchRow('larger','Larger text','A little easier to read',s)}${switchRow('wheelchair','Boarding assistance','Let your Captain know you may need help',s)}${switchRow('hearing','Hearing assistance','Prefer written trip communication',s)}${switchRow('notifications','Trip notifications','Stay with your journey',s)}${modalRow('Appearance','Light · matched to this design','settings','appearance')}</div>`;footer=action('Save preferences','save');break;
 case 'safety':body=`${intro('ALWAYS WITH YOU','A little peace of mind.','Your safety matters at every stage of the journey.')}<div class="safety-grid"><button class="safety-tile" data-modal="sos">${icon('shield')}<strong>Emergency help</strong><p>Find the right support when it matters.</p></button><button class="safety-tile" data-modal="share">${icon('location')}<strong>Share your trip</strong><p>Let someone you trust follow along.</p></button></div><div class="section-heading">Your safety toolkit</div><div class="group">${modalRow('Emergency contacts','Your trusted people','user','contacts')}${modalRow('Report a safety concern','Tell us about your journey','shield','report')}${modalRow('Safety guidance','A few good habits for every ride','file','safety-guide')}</div>`;break;
 case 'support':body=`${intro('WE’RE HERE','How can we help?','A little support goes a long way.')}<div class="safety-grid">${[['car','Trip issue','Pickup, cancellation or fare','report'],['wallet','Payments','Wallet, UPI and receipts','payment-help'],['user','Account','Sign-in and profile details','account-help'],['shield','Safety','Help on your journey','sos']].map(([ico,t,c,m])=>`<button class="safety-tile" data-modal="${m}">${icon(ico)}<strong>${t}</strong><p>${c}</p></button>`).join('')}</div><div class="section-heading">More help</div><div class="group">${modalRow('Left something behind?','Find support for a past trip','car','lost-item')}${modalRow('Contact support','Reach the Hop support team','chat','contact')}${modalRow('Frequently asked questions','A quick place to start','help','faq')}</div>`;break;
 case 'notifications':body=`${tabs(['All','Unread'],s.noticeTab||'All','notices')}<div class="row"><span class="small muted">Your updates</span><button class="text-button" data-action="read-all">Mark all as read</button></div>${[['shield','A good habit, every ride','Check the vehicle and plate before you get in.','Today'],['gift','A little more from Hop','Your rewards are ready to explore.','Yesterday']].map(([ico,t,c,time])=>`<div class="notification"><span class="list-symbol">${icon(ico)}</span><div style="flex:1"><strong>${t}</strong><p>${c}</p><small>${time}</small></div>${s.read?'':'<span class="notice-dot" aria-label="Unread"></span>'}</div>`).join('')}<div class="hint">Only the updates that help you on your way.</div>`;break;
 case 'saved':body=`${intro('YOUR FAMILIAR PLACES','A quicker way back.','Keep the places you use most close by.')}<div class="group">${row('Home','2nd Cross Street, Adyar','home','search')}${row('Work','Olympia Tech Park, Guindy','file','search')}</div><div class="section-heading">Somewhere else?</div><button class="secondary" data-modal="add-place">${icon('plus')} Add a place</button>`;break;
 case 'family':body=`${intro('MADE FOR YOUR PEOPLE','A little closer, together.','Book a ride for someone you care about.')}<div class="card"><span class="list-symbol">${icon('heart')}</span><h3>Your family, all in one place.</h3><p class="small muted">Invite your people for easier trip planning.</p><button class="secondary" data-modal="family-invite">Invite a family member</button></div><div class="section-heading">Favourite Captains</div><div class="group">${row('Arun Kumar','Auto · TN 09 AB 1234','car','search')}</div>`;break;
 case 'plan':body=`${intro('SOMETHING TO LOOK FORWARD TO','Plan your next hop.','A city ride, a few hours out, or a little further away.')}<label class="field-label" for="${role}-triptype">Trip type</label><select class="input" id="${role}-triptype"><option>City ride</option><option>Hourly rental</option><option>Outstation</option></select>${field('Pickup date & time',`${role}-schedule`,'','datetime-local')}<div class="route-summary">${route(s)}</div><button class="secondary" data-go="search">Choose your route</button><div class="hint">You’ll review the vehicle, availability and fare before confirming.</div>`;footer=primary('Review ride options','choose');break;
 case 'rewards':body=`${intro('GOOD JOURNEYS ADD UP','A little thank-you.','Invite your friends to discover Hop.')}<div class="balance-card"><span class="kicker">YOUR REWARD POINTS</span><div class="amount">240</div><p>From your journeys with Hop.</p></div><div class="section-heading">Bring a friend along</div><div class="card"><span class="kicker">YOUR REFERRAL CODE</span><h2 style="font-family:Outfit;letter-spacing:3px">HOPDEEPA</h2><p class="small muted">Good journeys are even better together.</p><button class="secondary" data-action="copy">${icon('file')} Copy preview code</button></div>`;break;
 case 'privacy':body=`${intro('YOUR ACCOUNT','A little more control.','Manage your information and account settings.')}<div class="group">${modalRow('Download my data','Your account information, together','file','export')}${modalRow('Privacy information','How your information is handled','lock','privacy-info')}${modalRow('Account deletion','Review the request and recovery process','user','delete-account')}</div><button class="secondary" style="margin-top:20px;color:#a64e3b" data-modal="signout">Sign out</button>`;break;
 case 'chat':body=`<p class="small muted" style="text-align:center">Today · Trip conversation preview</p><div class="chat-bubble">${captain?'I’m at the main entrance.':'Hi! I’m on my way to your pickup.'}</div>${s.chat.map(m=>`<div class="chat-bubble mine">${esc(m)}</div>`).join('')}<div class="chips">${['I’m at pickup','On my way','Main entrance'].map(m=>`<button data-message="${m}">${m}</button>`).join('')}</div>`;footer=`<form class="compose" data-chat-form><input class="input" aria-label="Message" placeholder="Write a message…" maxlength="500"><button class="icon-button" aria-label="Send preview message" type="submit">${icon('send')}</button></form>`;break;
 case 'request':isMap=true;sheet=`<div class="row"><span class="kicker">NEW TRIP REQUEST</span><span class="badge pending">1.2 km to pickup</span></div><div class="row" style="margin:14px 0"><div><h2>A good little trip.</h2><p class="small muted">Auto · City ride</p></div><div class="large-amount" style="font-size:36px">₹184</div></div><div class="route-summary">${route(s)}</div><div class="row"><span class="small muted">8.6 km trip</span><span class="small muted">About 22 minutes</span></div><div class="hint">Review the pickup and destination before accepting.</div>`;footer=`${primary('Accept ride','pickup')}<button class="text-button" style="width:100%;margin-top:5px" data-go="home">Not this time</button>`;break;
 case 'tools':body=`${intro('CAPTAIN TOOLKIT','Make your day work for you.','A few useful things for the road ahead.')}<div class="card"><div class="row"><span class="list-symbol">${icon('chart')}</span><strong style="flex:1">Daily earnings goal</strong><button class="text-button" data-modal="goal">Edit</button></div><div class="large-amount" style="font-size:29px">₹1,240 <span class="small muted">of ₹2,000</span></div><div style="height:6px;border-radius:10px;background:#eaf0e1"><i style="display:block;width:62%;height:100%;background:var(--accent);border-radius:10px"></i></div></div><div class="group">${switchRow('home','Head towards home','Prefer trips heading your way',s)}${row('Pickup & fare preferences','Radius and minimum fare','settings','preferences')}${row('Demand nearby','Explore pickup areas in your city','layers','demand')}${row('Driving insights','Your activity and rider feedback','chart','insights')}</div><button class="secondary" style="margin-top:18px" data-modal="break">Take a break</button>`;break;
 case 'vehicle':body=`<div class="vehicle-hero">${img('auto')}<strong>Bajaj RE</strong><small>Auto · TN 09 AB 1234</small></div><div class="card row"><strong>Application status</strong><span class="badge">Approved</span></div><div class="section-heading">Your documents</div><div class="group">${modalRow('Driving licence','Valid until 14 Jun 2030','file','document')}${modalRow('Registration certificate','Verified with your vehicle','car','document')}${modalRow('Vehicle insurance','Valid until 30 Sep 2027','shield','document')}</div><button class="secondary" style="margin-top:18px" data-go="onboarding">View Captain application</button>`;break;
 case 'insights':body=`${intro('YOUR DRIVING','Every trip adds up.','A clear view of your time on the road.')}<div class="metric-grid">${metric('Completed trips','128')}${metric('Distance travelled','986 km')}${metric('Average fare','₹186')}${metric('Average pickup','4 min')}${metric('Rider rating','4.9 / 5')}${metric('Best fare','₹482')}</div><div class="section-heading">Popular destinations</div><div class="group">${row('Chennai Airport','28 trips · ₹5,208','pin','activity')}${row('Guindy','19 trips · ₹3,462','pin','activity')}</div>`;break;
 case 'demand':isMap=true;sheet=`<span class="kicker">YOUR CITY, AT A GLANCE</span><h2>Where the city’s moving.</h2><p>Illustrative pickup areas for this design preview.</p><div class="group">${row('Guindy','2.1 km away · sample pickup area','pin','home')}${row('Adyar','1.4 km away · sample pickup area','pin','home')}</div>`;break;
 case 'ledger':body=`${intro('YOUR MONEY','Clear from start to finish.','Fares, wallet entries and payouts, together.')}<div class="balance-card"><span class="kicker">${captain?'AVAILABLE FOR PAYOUT':'YOUR WALLET BALANCE'}</span><div class="amount">${captain?'₹2,480':'₹680'}</div><p>Sample balance · design preview</p><button class="secondary" data-modal="${captain?'payout':'topup'}">${captain?'Request payout':'Add money'}</button></div><div class="section-heading">Recent entries</div><div class="group">${row('Trip fare · Airport','Today, 10:24 AM · +₹184','car','receipt')}${row('Trip fare · Guindy','Today, 9:10 AM · +₹146','car','receipt')}${row('Payout request','Yesterday · −₹1,200','wallet','receipt')}</div>`;break;
 case 'onboarding':{const steps=['First, a little about you.','Your vehicle, ready to go.','A few important documents.','Everything in one place.'];body=`<span class="kicker">STEP ${s.step+1} OF 4</span><div class="progress-steps">${[0,1,2,3].map(n=>`<i class="${n<=s.step?'done':''}"></i>`).join('')}</div>${intro('WELCOME TO HOP',steps[s.step],'Your information is reviewed before you start driving.')}${s.step===0?field('Full legal name',`${role}-legalname`,'Arun Kumar')+field('Mobile number',`${role}-mobile`,'9876543210','tel')+field('Operating city',`${role}-city`,'Chennai'):s.step===1?`<div class="vehicle-hero">${img(s.vehicle)}</div>`+field('Vehicle number',`${role}-number`,'TN 09 AB 1234')+field('Make & model',`${role}-model`,'Bajaj RE'):s.step===2?['Driving licence','Registration certificate','Insurance'].map(x=>`<div class="card row"><span class="list-symbol">${icon('file')}</span><strong class="small" style="flex:1">${x}</strong><button class="text-button" data-modal="upload">Add</button></div>`).join(''):`<div class="profile"><span class="avatar">A</span><div><strong>Arun Kumar</strong><p>Chennai · Auto</p></div></div><div class="group">${row('Vehicle details','TN 09 AB 1234 · Bajaj RE','car','vehicle')}${row('Documents','Ready for review in this preview','file','vehicle')}</div><div class="hint">Submission and operator approval are separate steps. This prototype does not submit an application.</div>`}`;footer=action(s.step===3?'Preview review status':'Continue','onboard-next');break;}
 case 'auth':body=`<div class="auth-hero"><span class="wordmark">hop<small>${role.toUpperCase()}</small></span><h2>${captain?'Your next chapter.<br>Just a hop away.':'Good journeys.<br>Every day.'}</h2><p>${captain?'Make your next move with Hop.':'Your city. Your people. Your way.'}</p>${img(captain?'mini':'auto')}</div><div class="intro" style="margin-top:25px"><span class="kicker">LET’S GET STARTED</span><h2 style="font-size:24px">Welcome to Hop.</h2><p>Sign in with your mobile number.</p></div>${field('Mobile number',`${role}-signin`,'','tel','Your 10-digit number')}<div class="hint">We’ll use an SMS code to sign you in. This is a layout preview; no SMS is sent.</div>`;footer=action('Preview verification step','auth-next');break;
 default:body=intro('YOUR HOP','A little closer.','Explore your journey with Hop.');
 }
 return {title,body,footer,isMap,sheet,hasNav};}
function places(query=''){const data=[['Chennai Airport','Departures · Terminal 1','location'],['Chennai Central','Pickup bay · Central Station','pin'],['T. Nagar','Pondy Bazaar · Chennai','pin'],['Marina Beach','Light House entrance','pin']].filter(([n])=>n.toLowerCase().includes(query.toLowerCase()));return data.length?data.map(([n,d,i])=>`<button class="place" data-destination="${n}"><span class="list-symbol">${icon(i)}</span><span><strong>${n}</strong><small>${d}</small></span></button>`).join(''):'<div class="hint">No matching preview places. Try Airport, Central, T. Nagar or Marina.</div>';}
function tripCard(s,time,status){return `<div class="trip-card"><div class="row"><span class="badge ${status==='Scheduled'?'pending':''}">${status}</span><strong>₹${currentVehicle(s).fare}</strong></div><p class="small muted">${time}</p>${route(s)}<div class="row"><span class="small muted">${currentVehicle(s).name} · ${s.payment}</span><button class="text-button" data-go="${status==='In progress'?'tracking':'receipt'}">${status==='In progress'?'View trip':'Payment & receipt'} →</button></div></div>`;}
function render(role,scroll=0){const s=state[role],host=document.querySelector(`[data-role=${role}] .phone`),v=view(role,s);host.dataset.screen=s.screen;host.classList.toggle('large-text',!!s.toggles.larger);host.innerHTML=`${header(role,s,v.title,!['home','account','wallet','earnings','activity'].includes(s.screen))}<div class="app-body ${v.isMap?'map-body':''}">${v.isMap?`${map(s,role)}<section class="sheet"><div class="handle"></div>${v.sheet}</section>`:`<div class="content">${v.body}</div>`}</div>${v.footer?`<footer class="actions">${v.footer}</footer>`:''}${v.hasNav?nav(role,s):''}`;host.querySelector('.app-body').scrollTop=scroll;document.querySelector(`[data-role=${role}] select[data-screen]`).value=s.screen;host.classList.remove('screen-enter');requestAnimationFrame(()=>host.classList.add('screen-enter'));}
function go(role,screen){if(!screens[role].some(([id])=>id===screen))return;state[role].screen=screen;render(role);}
function toast(role,text){const host=document.querySelector(`[data-role=${role}] .phone`);host.querySelector('.toast')?.remove();const e=document.createElement('div');e.className='toast';e.setAttribute('role','status');e.textContent=text;host.append(e);setTimeout(()=>e.remove(),4200);}
function closeModal(role){const host=document.querySelector(`[data-role=${role}] .phone`),scrim=host.querySelector('.modal-scrim');if(!scrim)return;scrim.remove();for(const child of host.children)child.inert=false;const previous=state[role].returnFocus;if(previous?.isConnected)previous.focus({preventScroll:true});}
function modal(role,name){const s=state[role],host=document.querySelector(`[data-role=${role}] .phone`);closeModal(role);s.returnFocus=document.activeElement;for(const child of host.children)child.inert=true;let title='A little more information',copy='This is a presentation-only preview. No account, payment or ride action will be sent.',body='';
 if(name==='payment'){title='How would you like to pay?';copy='A clear choice, before you go.';body=`<div class="group">${['Cash','Wallet','UPI'].map(x=>`<button class="list-row" data-payment="${x}"><span class="list-symbol">${icon('wallet')}</span><span class="list-copy"><strong>${x}</strong><small>${x===s.payment?'Your selected method':'Choose for this preview'}</small></span><i class="radio ${x===s.payment?'selected':''}"></i></button>`).join('')}</div>`;}
 else if(name==='vehicle-default'){title='Your usual ride';copy='Choose a default vehicle for the next preview journey.';body=vehicles.map(x=>`<button class="vehicle-card ${s.vehicle===x.id?'selected':''}" data-default="${x.id}">${img(x.id)}<span class="copy"><strong>${x.name}</strong><small>${x.detail}</small></span><i class="radio"></i></button>`).join('');}
 else if(name==='fare'){title='Your fare, clearly';copy='Illustrative pricing for this concept.';body=`<div class="fare-row"><span>Ride fare</span><strong>₹${currentVehicle(s).fare-10}</strong></div><div class="fare-row"><span>Booking fee</span><strong>₹10</strong></div><div class="fare-row total"><span>Estimated total</span><strong>₹${currentVehicle(s).fare}</strong></div>`;}
 else if(name==='cancel'){title='A change of plans?';copy='You can review the cancellation details before leaving your journey.';body=`<button class="primary" data-go="home">Return to Home preview</button>`;}
 else if(['topup','payout','goal','radius','minimum-fare'].includes(name)){title={topup:'A little ready for the next ride.',payout:'Your payout request',goal:'Your daily goal',radius:'Your pickup radius','minimum-fare':'Your minimum fare'}[name];copy='Adjust the layout preview. No balance or account is changed.';body=field(name==='radius'?'Radius (km)':'Amount (₹)',`${role}-modal-amount`,name==='goal'?'2000':name==='radius'?'3':'500','number')+`<button class="primary" style="margin-top:18px" data-action="preview-save">Save preview choice</button>`;}
 else if(['email','mobile','business','personal-more','add-place','family-invite','passenger','promo','report','lost-item'].includes(name)){title={'email':'Email address',mobile:'Mobile number',business:'Business receipt details','personal-more':'Personal details','add-place':'Save a familiar place','family-invite':'Invite your people',passenger:'Who’s riding?',promo:'A little off your next ride',report:'Tell us what happened','lost-item':'Left something behind?'}[name];body=field(['email'].includes(name)?'Email address':['promo'].includes(name)?'Promo code':['report','lost-item'].includes(name)?'Describe the issue':'Details',`${role}-modal-value`,'','text','Enter details')+`<button class="primary" style="margin-top:18px" data-action="preview-save">Save preview details</button>`;}
 else if(name==='language'){title='Your language';copy='Choose the language layout you’d like to see.';body='<select class="input" aria-label="Language"><option>English</option><option>Tamil</option><option>Hindi</option></select><div class="hint">Full translations are outside this visual prototype.</div>';}
 else if(name==='sos'){title='Help when it matters.';copy='Emergency actions stay easy to reach during a trip. This preview does not contact an operator or emergency service.';body='<div class="hint">For an actual emergency, use your device’s emergency calling options.</div>';}
 else if(name==='document'||name==='upload'){title='Your documents, together.';copy='Document-upload presentation. No private document is opened or uploaded.';body=`<div class="document-symbol">${icon('file')}</div><button class="secondary" data-action="preview-save">Preview document selection</button>`;}
 else {const data={share:['Share your journey','A trusted person can follow a trip once you create a real sharing link.'],call:['Call your trip partner','A call action will use the contact details provided by the live trip service.'],contact:['A little support','Booking, payments or your account—Hop support will help you find the right next step.'],contacts:['Your trusted people','Keep emergency contacts close by for your journeys.'],break:['A little pause goes a long way.','Take a break before getting back on the road.'],appearance:['A calmer, lighter Hop','This direction uses light surfaces, forest details and your application’s coral or gold accent.'],'safety-guide':['A few good habits','Check the vehicle and plate. Share the code only after meeting your Captain. Keep a trusted person informed.'],signout:['Until your next hop.','Sign-out requires confirmation in the real app. No session changes occur here.'],'delete-account':['Your account, your choice','Deletion requests and recovery periods must be explained before confirmation. No request is submitted here.']};[title,copy]=data[name]||[name.replaceAll('-',' ').replace(/^./,m=>m.toUpperCase()),copy];}
 const scrim=document.createElement('div');scrim.className='modal-scrim';scrim.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="${role}-modal-title"><div class="handle"></div><div class="row"><h2 id="${role}-modal-title">${title}</h2><button class="icon-button" aria-label="Close dialog" data-action="close">${icon('close')}</button></div><p>${copy}</p>${body}</section>`;host.append(scrim);scrim.addEventListener('click',e=>{if(e.target===scrim)closeModal(role);});scrim.querySelector('button,input,select')?.focus({preventScroll:true});}
function init(){document.getElementById('gallery').innerHTML=['rider','captain'].map(role=>`<section class="concept" data-role="${role}" aria-label="${role} design preview"><div class="concept-tools"><strong>${role==='rider'?'Rider':'Captain'}</strong><select data-screen aria-label="${role} screen">${screens[role].map(([id,label])=>`<option value="${id}">${label}</option>`).join('')}</select><button class="advance" data-advance>Next stage →</button></div><article class="phone ${role}" aria-label="${role} prototype"></article></section>`).join('');for(const role of ['rider','captain']){render(role);const concept=document.querySelector(`[data-role=${role}]`);concept.querySelector('[data-screen]').addEventListener('change',e=>go(role,e.target.value));concept.querySelector('[data-advance]').addEventListener('click',()=>{const order=flow[role],i=order.indexOf(state[role].screen);go(role,order[(i+1)%order.length]);});concept.addEventListener('input',e=>{if(e.target.matches('[data-search]'))concept.querySelector('[data-places]').innerHTML=places(e.target.value);if(e.target.matches('[data-code]'))e.target.value=e.target.value.replace(/\D/g,'').slice(0,6);});concept.addEventListener('submit',e=>{e.preventDefault();if(e.target.matches('[data-chat-form]')){const input=e.target.querySelector('input');if(input.value.trim()){state[role].chat.push(input.value.trim());render(role);}}});concept.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const s=state[role],host=concept.querySelector('.phone');if(b.dataset.go){go(role,b.dataset.go);return;}if(b.dataset.destination){s.destination=b.dataset.destination;go(role,'choose');return;}if(b.dataset.vehicle){s.vehicle=b.dataset.vehicle;render(role);return;}if(b.dataset.homeVehicle){s.vehicle=b.dataset.homeVehicle;go(role,'search');return;}if(b.dataset.tab){if(b.dataset.kind==='history')s.tab=b.dataset.tab;else if(b.dataset.kind==='notices')s.noticeTab=b.dataset.tab;else s.sort=b.dataset.tab;render(role);return;}if(b.dataset.toggle){s.toggles[b.dataset.toggle]=!s.toggles[b.dataset.toggle];const scroll=host.querySelector('.app-body').scrollTop;render(role,scroll);return;}if(b.dataset.star){s.stars=Number(b.dataset.star);render(role);return;}if(b.dataset.message){s.chat.push(b.dataset.message);render(role);return;}if(b.dataset.payment){s.payment=b.dataset.payment;render(role);return;}if(b.dataset.default){s.vehicle=b.dataset.default;render(role);return;}if(b.dataset.modal){modal(role,b.dataset.modal);return;}switch(b.dataset.action){case'back':go(role,s.screen==='otp'?'pickup':'home');break;case'close':closeModal(role);break;case'online':s.online=!s.online;render(role);break;case'verify-code':if((host.querySelector('[data-code]')?.value||'').length===6)go(role,'trip');else toast(role,'Enter six digits to continue the layout preview.');break;case'onboard-next':if(s.step<3){s.step++;render(role);}else modal(role,'application-review');break;case'auth-next':modal(role,'verification-preview');break;case'read-all':s.read=true;render(role);break;case'payment-preview':toast(role,'Payment preview only. No charge was made and no settlement is confirmed.');break;case'preview-save':closeModal(role);toast(role,'Preview choice saved locally. No account or money was changed.');break;case'copy':toast(role,'Preview referral code: HOPDEEPA');break;case'centre':toast(role,'Illustrative map centred for this design preview.');break;case'save':toast(role,'Saved in this preview only. Your live account is unchanged.');break;}});}
 const params=new URLSearchParams(location.search);function selectView(value){document.body.dataset.view=value;document.querySelectorAll('button[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===value)));}selectView(['rider','captain'].includes(params.get('view'))?params.get('view'):'both');document.querySelectorAll('button[data-view]').forEach(b=>b.addEventListener('click',()=>{selectView(b.dataset.view);const url=new URL(location.href);url.searchParams.set('view',b.dataset.view);history.replaceState(null,'',url);}));document.addEventListener('keydown',e=>{const scrim=document.querySelector('.modal-scrim');if(!scrim)return;const role=scrim.closest('[data-role]').dataset.role;if(e.key==='Escape'){closeModal(role);return;}if(e.key==='Tab'){const controls=[...scrim.querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled&&x.getBoundingClientRect().width),first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});}
window.hopConcept={state,screens,go};init();
